  pct_b90_alive: number | null;
  b90_mark_coverage_pct: number | null;
  pct_na_unknown: number;     // % of eligible cost left out: latest NA status unknown
  pct_na_history_gap: number; // % counted as clear but with an earlier unknown quarter
  pct_not_yet_seen: number;   // % of eligible cost its holder had not shown yet (in no base)
  na_partial: boolean;
  hc_cost_share: number;      // % of counted cost with a HIGH or MED date
  pct_mod_unknown: number;    // % of eligible cost shown but with a modification history not judged
  mod_partial: boolean;       // pct_mod_unknown >= 5
  n_loans_1l: number;
  cohort_1l_b: number;
